const items = $input.all();
const webhookData = $('Webhook').first().json;
const startTime = Date.now();

function extractMetaTags(html) {
  const meta = {};

  // Title
  const titleMatch = html.match(/<title[^>]*>([^<]*)<\/title>/i);
  if (titleMatch) meta.title = titleMatch[1].trim();

  // Meta description
  const descMatch = html.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']*)["'][^>]*>/i) ||
                    html.match(/<meta[^>]*content=["']([^"']*)["'][^>]*name=["']description["'][^>]*>/i);
  if (descMatch) meta.description = descMatch[1];

  // OpenGraph
  const ogTags = {};
  const ogRegex = /<meta[^>]*property=["']og:([^"']*)["'][^>]*content=["']([^"']*)["'][^>]*>/gi;
  const ogRegex2 = /<meta[^>]*content=["']([^"']*)["'][^>]*property=["']og:([^"']*)["'][^>]*>/gi;
  let ogMatch;
  while ((ogMatch = ogRegex.exec(html)) !== null) {
    ogTags['og:' + ogMatch[1]] = ogMatch[2];
  }
  while ((ogMatch = ogRegex2.exec(html)) !== null) {
    ogTags['og:' + ogMatch[2]] = ogMatch[1];
  }

  // Twitter Cards
  const twitterTags = {};
  const twitterRegex = /<meta[^>]*name=["']twitter:([^"']*)["'][^>]*content=["']([^"']*)["'][^>]*>/gi;
  const twitterRegex2 = /<meta[^>]*content=["']([^"']*)["'][^>]*name=["']twitter:([^"']*)["'][^>]*>/gi;
  let twMatch;
  while ((twMatch = twitterRegex.exec(html)) !== null) {
    twitterTags['twitter:' + twMatch[1]] = twMatch[2];
  }
  while ((twMatch = twitterRegex2.exec(html)) !== null) {
    twitterTags['twitter:' + twMatch[2]] = twMatch[1];
  }

  // JSON-LD
  let jsonLd = null;
  const jsonLdMatch = html.match(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/i);
  if (jsonLdMatch) {
    try {
      jsonLd = JSON.parse(jsonLdMatch[1]);
    } catch (e) { /* ignore parse errors */ }
  }

  // Favicon
  let favicon = null;
  const faviconMatch = html.match(/<link[^>]*rel=["'](?:shortcut )?icon["'][^>]*href=["']([^"']*)["'][^>]*>/i) ||
                       html.match(/<link[^>]*href=["']([^"']*)["'][^>]*rel=["'](?:shortcut )?icon["'][^>]*>/i);
  if (faviconMatch) favicon = faviconMatch[1];

  // Author
  const authorMatch = html.match(/<meta[^>]*name=["']author["'][^>]*content=["']([^"']*)["'][^>]*>/i);
  if (authorMatch) meta.author = authorMatch[1];

  return {
    standard: meta,
    opengraph: ogTags,
    twitter: twitterTags,
    json_ld: jsonLd,
    favicon: favicon
  };
}

const results = items.map(item => {
  try {
    const html = item.json.html || item.json.body || '';
    const url = item.json.url || webhookData.body.data;

    if (!html && item.json.error) {
      return {
        json: {
          success: false,
          error: {
            code: 500,
            message: 'Failed to fetch URL: ' + (item.json.error.message || 'Unknown error'),
            status: 'FETCH_ERROR'
          },
          meta: {
            provider: 'http-extract',
            execution_mode: webhookData.body.execution_mode || 'online'
          }
        }
      };
    }

    const sources = extractMetaTags(html);

    // Build normalized metadata (priority: OG > Twitter > Standard)
    const normalized = {
      title: sources.opengraph['og:title'] || sources.twitter['twitter:title'] || sources.standard.title || null,
      description: sources.opengraph['og:description'] || sources.twitter['twitter:description'] || sources.standard.description || null,
      image: sources.opengraph['og:image'] || sources.twitter['twitter:image'] || null,
      url: sources.opengraph['og:url'] || url,
      site_name: sources.opengraph['og:site_name'] || null,
      type: sources.opengraph['og:type'] || null,
      author: sources.json_ld?.author?.name || sources.standard.author || null,
      published_time: sources.opengraph['og:article:published_time'] || sources.json_ld?.datePublished || null,
      favicon: sources.favicon
    };

    return {
      json: {
        success: true,
        data: {
          ...normalized,
          sources: sources
        },
        meta: {
          provider: 'http-extract',
          execution_mode: webhookData.body.execution_mode || 'online',
          cache_hit: false,
          processing_time_ms: Date.now() - startTime
        }
      }
    };
  } catch (e) {
    return {
      json: {
        success: false,
        error: {
          code: 500,
          message: 'Metadata extraction failed: ' + e.message,
          status: 'EXTRACT_ERROR'
        },
        meta: {
          provider: 'http-extract',
          execution_mode: webhookData.body.execution_mode || 'online'
        }
      }
    };
  }
});

return results;
